NTS","modo":"HEREDA","dueno":"TECNICO","titulo":"Resumen de plan durante pago","descripcion":"BLOQUEAR checkout de cuotas que oculte resumen lateral al interactuar con formulario de pago o no conserve número de cuotas, cuota mensual, total, acceso a cronograma y bloque Carta de No Adeudo, sin inventar datos ni prometer emisión.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s15c12_checkout_cuotas"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s15c12_interaccion_pago"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s15c12_resumen_oculto_o_incompleto"},"der":{"lit":true}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s15c12_checkout_cuotas":false,"s15c12_interaccion_pago":false,"s15c12_resumen_oculto_o_incompleto":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s15c12_checkout_cuotas":false,"s15c12_interaccion_pago":false,"s15c12_resumen_oculto_o_incompleto":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s15c12_checkout_cuotas":false,"s15c12_interaccion_pago":true,"s15c12_resumen_oculto_o_incompleto":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s15c12_checkout_cuotas":false,"s15c12_interaccion_pago":true,"s15c12_resumen_oculto_o_incompleto":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s15c12_checkout_cuotas":true,"s15c12_interaccion_pago":false,"s15c12_resumen_oculto_o_incompleto":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s15c12_checkout_cuotas":true,"s15c12_interaccion_pago":false,"s15c12_resumen_oculto_o_incompleto":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s15c12_checkout_cuotas":true,"s15c12_interaccion_pago":true,"s15c12_resumen_oculto_o_incompleto":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s15c12_checkout_cuotas":true,"s15c12_interaccion_pago":true,"s15c12_resumen_oculto_o_incompleto":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/291","solicitante":"Cristhian / Claude S15 2026-11-24"}}]$packets$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=substring(p->'origen'->>'ref' from '[0-9]+$')::int;
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND NOT EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid AND estado='VIGENTE' AND NOT coalesce(pendiente_decision,false)) THEN RAISE EXCEPTION 'S15_SOURCE_NOT_ELIGIBLE %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S15_ALREADY_COVERED %',lid; END IF;
 q:=lf_ops.nucleo_regla_proponer_v1(p,false);
 IF q->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (q->>'bloqueantes')::int<>0 THEN RAISE EXCEPTION 'S15_PREFLIGHT_FAIL % %',cd,q; END IF;
 q:=lf_ops.nucleo_regla_proponer_v1(p,true);
 IF q->>'resultado'<>'CANDIDATA' OR (q->>'version')::int<>1 THEN RAISE EXCEPTION 'S15_CREATE_FAIL % %',cd,q; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 OR (SELECT count(distinct entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 THEN RAISE EXCEPTION 'S15_VECTOR_INVALID %',cd; END IF;
 e:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF e->>'decision'<>'BLOQUEADA' OR e->>'hash_paquete' IS NULL THEN RAISE EXCEPTION 'S15_GATE_FAIL % %',cd,e; END IF;
 n:=n+1; RAISE NOTICE 'S15_CANDIDATE % hash=%',cd,e->>'hash_paquete';
 END LOOP;
 IF n<>12 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA')<>b_cand+12 OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla LIKE 'S15-C%')<>96
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada t) IS DISTINCT FROM b_bridge
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones t WHERE estado='PUBLICADA') IS DISTINCT FROM b_pub
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.nucleo_juicios t) IS DISTINCT FROM b_judge THEN RAISE EXCEPTION 'S15_CONSERVATION_FAIL'; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.pantallas WHERE id=36) AND jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S15_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S15_PASS 12 CANDIDATAS 96 VECTORES 0 PROMOCIONES';
END $s15$;
COMMIT;
